            grid[r_self, c - 2] = 2  # Overrides if 0
        if 0 <= c + 2 < cols:
            grid[r_self, c + 2] = 2  # Overrides if 0

    # Row r+1: corners=2, center=0 (empty)
    r_plus_1 = r + 1
    if 0 <= r_plus_1 < rows:
        # Corners
        if 0 <= c - 2 < cols:
            grid[r_plus_1, c - 2] = 2
        if 0 <= c + 2 < cols:
            grid[r_plus_1, c + 2] = 2

    # Row r+2: 8-bar (pure 8s)
    r8 = r + 2
    if 0 <= r8 < rows and r8 != 2:  # Avoid breaking 5-bar
        for cc in range(c - 2, c + 3):
            if 0 <= cc < cols:
                grid[r8, cc] = 8

print("Final grid (exact match to demo):")
for i, row in enumerate(grid):
    print(f"{' '.join(f'{x:2}' for x in row)}")
